import React from 'react';
import TextWindow from './TextWindow';
import ImageWindow from './ImageWindow';
import ImageTextWindow from './ImageTextWindow';

function Window(props) {
    const { type, content, image, text } = props;

    let windowContent;

    switch (type) {
        case 'text':
            windowContent = <TextWindow text={content} />;
            break;
        case 'image':
            windowContent = <ImageWindow src={image} alt={content} />;
            break;
        case 'imageWithText':
            windowContent = <ImageTextWindow src={image} text={text} />;
            break;
        default:
            windowContent = <div>No content available</div>;
    }

    return (
        <div className="window">
            <div className="window-content">
                {windowContent}
            </div>
        </div>
    );
}

export default Window;
